SELECT COUNT(MN.MENU_ID)
  FROM TB_SYME001 MN
       INNER JOIN TB_SYME002 RO
    ON MN.MENU_ID = RO.MENU_ID
 WHERE RO.ROLE_TP = #{roleAuthority.roleType, typeHandler=UserRoleTypeHandler}
   AND MN.HI_MNU_ID = #{roleAuthority.menuId};

